`default_nettype none

// -----------------------------------------------------------------------------
// AUTO-GENERATED by gen_bandpass.py -- do not edit by hand, regenerate instead.
//
// 4th-order Butterworth bandpass, 50 Hz - 800 Hz @ fs = 48000 Hz
// Cascade of two biquads (Direct Form I), multiplier-free: every constant
// multiplication is a hard-wired canonical-signed-digit (CSD) shift-add tree.
//
//   y[n] = b0*x[n] + b1*x[n-1] + b2*x[n-2] + fa1*y[n-1] + fa2*y[n-2]     (fa = -a)
//
// Coefficients are signed fixed point with 24 fractional bits:
//   section 1: b0=37775 b1=75550 b2=37775  fa1=31358887 fa2=-14735711
//      real    : b0=+0.002251565 b1=+0.004503131 b2=+0.002251565 fa1=+1.869135320 fa2=-0.878316820
//      CSD g   : +2^15 +2^12 +2^10 -2^7 +2^4 -2^0
//      CSD fa1 : +2^25 -2^21 -2^17 +2^15 -2^7 +2^5 +2^3 -2^0
//      CSD fa2 : -2^24 +2^21 -2^16 +2^13 +2^11 -2^9 +2^7 +2^5 +2^0
//   section 2: b0=16777216 b1=-33554432 b2=16777216  fa1=33401785 fa2=-16625371
//      real    : b0=+1.000000000 b1=-2.000000000 b2=+1.000000000 fa1=+1.990901530 fa2=-0.990949333
//      CSD g   : +2^24
//      CSD fa1 : +2^25 -2^17 -2^14 -2^12 -2^10 -2^6 -2^3 +2^0
//      CSD fa2 : -2^24 +2^17 +2^14 +2^12 +2^8 +2^5 +2^2 +2^0
//
// Numerator is factored as g*(x0 +- 2*x1 + x2) so only g needs a CSD tree.
//
// Hardware summary
//   adders (wide)    : 44  (no multipliers, no DSP blocks required)
//   pipeline every   : 2 adder levels (0 = fully combinational)
//   settle latency   : 4 clocks per section (inputs are held constant, so the
//                      pipelined trees simply settle; the FSM waits LAT clocks)
//   per-sample cost  : about 16 clocks + memory handshake
//
// Number formats
//   sample_in / output : signed integer, BIT_WIDTH bits (raw PCM)
//   internal state     : sample << GUARD_BITS (GUARD_BITS extra fractional bits)
//   rounding           : round-to-nearest; saturation after each section & at output
//
// Memory handshake: after a sample is computed, address/val_out are loaded, then
// start_write goes high and stays high until a rising edge of `res` (a response
// strobe that must be low between transactions; synchronized internally).
// -----------------------------------------------------------------------------
module Bandpass_Filter #(
    parameter int BIT_WIDTH  = 24,
    parameter int FRAME_LEN  = 1920,
    parameter int GUARD_BITS = 12   // must be >= 1
) (
    input  logic                        rst_n,
    input  logic                        clk,
    input  logic                        start,
    input  logic [BIT_WIDTH-1:0]        frame_addr_base,
    input  logic signed [BIT_WIDTH-1:0] sample_in,
    output logic                        busy,

    // Memory interface
    output logic                        start_read,   // unused, tied low
    output logic                        start_write,
    output logic [BIT_WIDTH-1:0]        address,
    output logic [BIT_WIDTH-1:0]        val_out,
    input  logic [BIT_WIDTH-1:0]        val_in,       // unused
    input  logic                        res
);

    // -------------------------------------------------------------------------
    // Widths and constants
    // -------------------------------------------------------------------------
    localparam int COEF_FRAC = 24;
    localparam int LAT       = 4;
    localparam int STATE_W   = BIT_WIDTH + GUARD_BITS;
    localparam int ACC_W     = STATE_W + COEF_FRAC + 4;
    localparam int SN_W      = $clog2(FRAME_LEN);

    // +0.5 LSB (at the COEF_FRAC scale) added into every sum => round-to-nearest
    localparam logic signed [ACC_W-1:0] ROUND_CONST =
        {{(ACC_W-COEF_FRAC){1'b0}}, 1'b1, {(COEF_FRAC-1){1'b0}}};

    // Saturation limits for a STATE_W-bit value, expressed in ACC_W bits
    localparam logic signed [ACC_W-1:0] ST_MAX =
        {{(ACC_W-STATE_W+1){1'b0}}, {(STATE_W-1){1'b1}}};
    localparam logic signed [ACC_W-1:0] ST_MIN =
        {{(ACC_W-STATE_W+1){1'b1}}, {(STATE_W-1){1'b0}}};

    // Final-output rounding / saturation (STATE_W+1 bits wide)
    localparam logic signed [STATE_W:0] HALF_G =
        {{(STATE_W+1-GUARD_BITS){1'b0}}, 1'b1, {(GUARD_BITS-1){1'b0}}};
    localparam logic signed [STATE_W:0] OUT_MAX =
        {{(GUARD_BITS+2){1'b0}}, {(BIT_WIDTH-1){1'b1}}};
    localparam logic signed [STATE_W:0] OUT_MIN =
        {{(GUARD_BITS+2){1'b1}}, {(BIT_WIDTH-1){1'b0}}};

    // -------------------------------------------------------------------------
    // State
    // -------------------------------------------------------------------------
    typedef enum logic [2:0] {
        S_IDLE,
        S_SEC1,
        S_SEC2,
        S_ROUND,
        S_WRITE_REQ,
        S_WRITE_WAIT
    } state_t;

    state_t state;

    logic [$clog2(LAT+2)-1:0]  wcnt;
    logic signed [STATE_W-1:0] s1_in, s1_x1, s1_x2, s1_y1, s1_y2;   // section 1
    logic signed [STATE_W-1:0] s2_in, s2_x1, s2_x2, s2_y1, s2_y2;   // section 2
    logic signed [STATE_W-1:0] y_sec;                               // final section output

    logic [SN_W-1:0]           sample_num;
    logic [1:0]                res_sync;
    logic                      res_prev;
    logic                      res_posedge;

    assign res_posedge = res_sync[1] & ~res_prev;
    assign busy        = (state != S_IDLE);
    assign start_read  = 1'b0;

    // -------------------------------------------------------------------------
    // Shift-add trees (generated). Inputs are the state registers above.
    // -------------------------------------------------------------------------
    // ---- Section 1 (factored numerator) ----
    logic signed [ACC_W-1:0] s1_ex_in;
    assign s1_ex_in = {{(ACC_W-STATE_W){s1_in[STATE_W-1]}}, s1_in};
    logic signed [ACC_W-1:0] s1_ex_x1;
    assign s1_ex_x1 = {{(ACC_W-STATE_W){s1_x1[STATE_W-1]}}, s1_x1};
    logic signed [ACC_W-1:0] s1_ex_x2;
    assign s1_ex_x2 = {{(ACC_W-STATE_W){s1_x2[STATE_W-1]}}, s1_x2};
    logic signed [ACC_W-1:0] s1_ex_y1;
    assign s1_ex_y1 = {{(ACC_W-STATE_W){s1_y1[STATE_W-1]}}, s1_y1};
    logic signed [ACC_W-1:0] s1_ex_y2;
    assign s1_ex_y2 = {{(ACC_W-STATE_W){s1_y2[STATE_W-1]}}, s1_y2};
    logic signed [ACC_W-1:0] s1_prep_1;
    logic signed [ACC_W-1:0] s1_prep_2;
    logic signed [ACC_W-1:0] s1_prep_2_q;
    logic signed [ACC_W-1:0] s1_tp_3;
    logic signed [ACC_W-1:0] s1_tp_4;
    logic signed [ACC_W-1:0] s1_tp_5;
    logic signed [ACC_W-1:0] s1_tp_6;
    logic signed [ACC_W-1:0] s1_tp_7;
    logic signed [ACC_W-1:0] s1_tp_8;
    logic signed [ACC_W-1:0] s1_tp_8_q;
    logic signed [ACC_W-1:0] s1_tp_9;
    logic signed [ACC_W-1:0] s1_tp_9_q;
    logic signed [ACC_W-1:0] s1_tp_10;
    logic signed [ACC_W-1:0] s1_tp_10_q;
    logic signed [ACC_W-1:0] s1_tp_11;
    logic signed [ACC_W-1:0] s1_tp_12;
    logic signed [ACC_W-1:0] s1_tp_13;
    logic signed [ACC_W-1:0] s1_tp_14;
    logic signed [ACC_W-1:0] s1_tp_14_q;
    logic signed [ACC_W-1:0] s1_tp_15;
    logic signed [ACC_W-1:0] s1_tp_15_q;
    logic signed [ACC_W-1:0] s1_tp_16;
    logic signed [ACC_W-1:0] s1_tn_17;
    logic signed [ACC_W-1:0] s1_tn_18;
    logic signed [ACC_W-1:0] s1_tn_19;
    logic signed [ACC_W-1:0] s1_tn_20;
    logic signed [ACC_W-1:0] s1_tn_20_q;
    logic signed [ACC_W-1:0] s1_tn_21;
    logic signed [ACC_W-1:0] s1_tn_21_q;
    logic signed [ACC_W-1:0] s1_tn_22;
    logic signed [ACC_W-1:0] s1_tn_23;
    logic signed [ACC_W-1:0] s1_tn_24;
    logic signed [ACC_W-1:0] s1_tn_24_q;
    logic signed [ACC_W-1:0] s1_t_25;
    logic signed [ACC_W-1:0] s1_t_25_q;
    assign s1_prep_1 = s1_ex_in + s1_ex_x2;
    assign s1_prep_2 = (s1_ex_x1 <<< 1) + s1_prep_1;
    assign s1_tp_3 = (s1_ex_y1 <<< 3) + (s1_ex_y1 <<< 5);
    assign s1_tp_4 = (s1_ex_y1 <<< 15) + (s1_ex_y1 <<< 25);
    assign s1_tp_5 = s1_ex_y2 + (s1_ex_y2 <<< 5);
    assign s1_tp_6 = (s1_ex_y2 <<< 7) + (s1_ex_y2 <<< 11);
    assign s1_tp_7 = (s1_ex_y2 <<< 13) + (s1_ex_y2 <<< 21);
    assign s1_tp_8 = ROUND_CONST + s1_tp_3;
    assign s1_tp_9 = s1_tp_4 + s1_tp_5;
    assign s1_tp_10 = s1_tp_6 + s1_tp_7;
    assign s1_tp_11 = (s1_prep_2_q <<< 4) + (s1_prep_2_q <<< 10);
    assign s1_tp_12 = (s1_prep_2_q <<< 12) + (s1_prep_2_q <<< 15);
    assign s1_tp_13 = s1_tp_8_q + s1_tp_9_q;
    assign s1_tp_14 = s1_tp_10_q + s1_tp_11;
    assign s1_tp_15 = s1_tp_12 + s1_tp_13;
    assign s1_tp_16 = s1_tp_14_q + s1_tp_15_q;
    assign s1_tn_17 = s1_ex_y1 + (s1_ex_y1 <<< 7);
    assign s1_tn_18 = (s1_ex_y1 <<< 17) + (s1_ex_y1 <<< 21);
    assign s1_tn_19 = (s1_ex_y2 <<< 9) + (s1_ex_y2 <<< 16);
    assign s1_tn_20 = (s1_ex_y2 <<< 24) + s1_tn_17;
    assign s1_tn_21 = s1_tn_18 + s1_tn_19;
    assign s1_tn_22 = s1_prep_2_q + (s1_prep_2_q <<< 7);
    assign s1_tn_23 = s1_tn_20_q + s1_tn_21_q;
    assign s1_tn_24 = s1_tn_22 + s1_tn_23;
    assign s1_t_25 = s1_tp_16 - s1_tn_24_q;
    always_ff @(posedge clk) begin   // pipeline registers (free-running, no reset)
        s1_prep_2_q <= s1_prep_2;
        s1_tp_8_q <= s1_tp_8;
        s1_tp_9_q <= s1_tp_9;
        s1_tp_10_q <= s1_tp_10;
        s1_tp_14_q <= s1_tp_14;
        s1_tp_15_q <= s1_tp_15;
        s1_tn_20_q <= s1_tn_20;
        s1_tn_21_q <= s1_tn_21;
        s1_tn_24_q <= s1_tn_24;
        s1_t_25_q <= s1_t_25;
    end
    logic signed [ACC_W-1:0] acc1;
    assign acc1 = s1_t_25_q;

    // ---- Section 2 (factored numerator) ----
    logic signed [ACC_W-1:0] s2_ex_in;
    assign s2_ex_in = {{(ACC_W-STATE_W){s2_in[STATE_W-1]}}, s2_in};
    logic signed [ACC_W-1:0] s2_ex_x1;
    assign s2_ex_x1 = {{(ACC_W-STATE_W){s2_x1[STATE_W-1]}}, s2_x1};
    logic signed [ACC_W-1:0] s2_ex_x2;
    assign s2_ex_x2 = {{(ACC_W-STATE_W){s2_x2[STATE_W-1]}}, s2_x2};
    logic signed [ACC_W-1:0] s2_ex_y1;
    assign s2_ex_y1 = {{(ACC_W-STATE_W){s2_y1[STATE_W-1]}}, s2_y1};
    logic signed [ACC_W-1:0] s2_ex_y2;
    assign s2_ex_y2 = {{(ACC_W-STATE_W){s2_y2[STATE_W-1]}}, s2_y2};
    logic signed [ACC_W-1:0] s2_prep_26;
    logic signed [ACC_W-1:0] s2_pre_27;
    logic signed [ACC_W-1:0] s2_pre_27_q;
    logic signed [ACC_W-1:0] s2_tp_28;
    logic signed [ACC_W-1:0] s2_tp_29;
    logic signed [ACC_W-1:0] s2_tp_30;
    logic signed [ACC_W-1:0] s2_tp_31;
    logic signed [ACC_W-1:0] s2_tp_32;
    logic signed [ACC_W-1:0] s2_tp_33;
    logic signed [ACC_W-1:0] s2_tp_33_q;
    logic signed [ACC_W-1:0] s2_tp_34;
    logic signed [ACC_W-1:0] s2_tp_34_q;
    logic signed [ACC_W-1:0] s2_tp_35;
    logic signed [ACC_W-1:0] s2_tp_35_q;
    logic signed [ACC_W-1:0] s2_tp_36;
    logic signed [ACC_W-1:0] s2_tp_37;
    logic signed [ACC_W-1:0] s2_tp_37_q;
    logic signed [ACC_W-1:0] s2_tn_38;
    logic signed [ACC_W-1:0] s2_tn_39;
    logic signed [ACC_W-1:0] s2_tn_40;
    logic signed [ACC_W-1:0] s2_tn_41;
    logic signed [ACC_W-1:0] s2_tn_41_q;
    logic signed [ACC_W-1:0] s2_tn_42;
    logic signed [ACC_W-1:0] s2_tn_42_q;
    logic signed [ACC_W-1:0] s2_tn_43;
    logic signed [ACC_W-1:0] s2_t_44;
    logic signed [ACC_W-1:0] s2_t_44_q;
    assign s2_prep_26 = s2_ex_in + s2_ex_x2;
    assign s2_pre_27 = s2_prep_26 - (s2_ex_x1 <<< 1);
    assign s2_tp_28 = s2_ex_y1 + (s2_ex_y1 <<< 25);
    assign s2_tp_29 = s2_ex_y2 + (s2_ex_y2 <<< 2);
    assign s2_tp_30 = (s2_ex_y2 <<< 5) + (s2_ex_y2 <<< 8);
    assign s2_tp_31 = (s2_ex_y2 <<< 12) + (s2_ex_y2 <<< 14);
    assign s2_tp_32 = (s2_ex_y2 <<< 17) + ROUND_CONST;
    assign s2_tp_33 = s2_tp_28 + s2_tp_29;
    assign s2_tp_34 = s2_tp_30 + s2_tp_31;
    assign s2_tp_35 = s2_tp_32 + (s2_pre_27_q <<< 24);
    assign s2_tp_36 = s2_tp_33_q + s2_tp_34_q;
    assign s2_tp_37 = s2_tp_36 + s2_tp_35_q;
    assign s2_tn_38 = (s2_ex_y1 <<< 3) + (s2_ex_y1 <<< 6);
    assign s2_tn_39 = (s2_ex_y1 <<< 10) + (s2_ex_y1 <<< 12);
    assign s2_tn_40 = (s2_ex_y1 <<< 14) + (s2_ex_y1 <<< 17);
    assign s2_tn_41 = (s2_ex_y2 <<< 24) + s2_tn_38;
    assign s2_tn_42 = s2_tn_39 + s2_tn_40;
    assign s2_tn_43 = s2_tn_41_q + s2_tn_42_q;
    assign s2_t_44 = s2_tp_37_q - s2_tn_43;
    always_ff @(posedge clk) begin   // pipeline registers (free-running, no reset)
        s2_pre_27_q <= s2_pre_27;
        s2_tp_33_q <= s2_tp_33;
        s2_tp_34_q <= s2_tp_34;
        s2_tp_35_q <= s2_tp_35;
        s2_tp_37_q <= s2_tp_37;
        s2_tn_41_q <= s2_tn_41;
        s2_tn_42_q <= s2_tn_42;
        s2_t_44_q <= s2_t_44;
    end
    logic signed [ACC_W-1:0] acc2;
    assign acc2 = s2_t_44_q;


    // -------------------------------------------------------------------------
    // Saturate a full-scale sum back to STATE_W bits
    // -------------------------------------------------------------------------
    function automatic logic signed [STATE_W-1:0] sat_state(input logic signed [ACC_W-1:0] a);
        logic signed [ACC_W-1:0] s;
        begin
            s = a >>> COEF_FRAC;
            if (s > ST_MAX)      sat_state = ST_MAX[STATE_W-1:0];
            else if (s < ST_MIN) sat_state = ST_MIN[STATE_W-1:0];
            else                 sat_state = s[STATE_W-1:0];
        end
    endfunction

    // Final output: drop guard bits with round-to-nearest, saturate to BIT_WIDTH.
    // NOTE: a concatenation is always unsigned, so $signed() is required for the
    // >>> to be an arithmetic shift.
    logic signed [STATE_W:0]     y_rnd;
    logic signed [BIT_WIDTH-1:0] y_final;

    assign y_rnd = ($signed({y_sec[STATE_W-1], y_sec}) + HALF_G) >>> GUARD_BITS;

    always_comb begin
        if (y_rnd > OUT_MAX)      y_final = OUT_MAX[BIT_WIDTH-1:0];
        else if (y_rnd < OUT_MIN) y_final = OUT_MIN[BIT_WIDTH-1:0];
        else                      y_final = y_rnd[BIT_WIDTH-1:0];
    end

    // Byte offset of this sample within the frame (4 bytes per sample)
    logic [BIT_WIDTH-1:0] sample_off;
    assign sample_off = {{(BIT_WIDTH-SN_W-2){1'b0}}, sample_num, 2'b00};

    // -------------------------------------------------------------------------
    // Control
    // -------------------------------------------------------------------------
    always_ff @(posedge clk or negedge rst_n) begin
        if (!rst_n) begin
            state       <= S_IDLE;
            wcnt        <= '0;
            s1_in <= '0; s1_x1 <= '0; s1_x2 <= '0; s1_y1 <= '0; s1_y2 <= '0;
            s2_in <= '0; s2_x1 <= '0; s2_x2 <= '0; s2_y1 <= '0; s2_y2 <= '0;
            y_sec       <= '0;
            sample_num  <= '0;
            res_sync    <= '0;
            res_prev    <= 1'b0;
            start_write <= 1'b0;
            address     <= '0;
            val_out     <= '0;
        end else begin
            // 2-FF synchronizer + 1 FF for edge detect
            res_sync <= {res_sync[0], res};
            res_prev <= res_sync[1];

            case (state)
                // Latch the input sample on `start` so it may change afterwards
                S_IDLE: begin
                    if (start) begin
                        s1_in <= {sample_in, {GUARD_BITS{1'b0}}};
                        wcnt  <= '0;
                        state <= S_SEC1;
                    end
                end

                // Wait for the section-1 tree to settle, then latch and shift history
                S_SEC1: begin
                    if (wcnt == LAT) begin
                        s1_x1 <= s1_in;
                        s1_x2 <= s1_x1;
                        s1_y1 <= sat_state(acc1);
                        s1_y2 <= s1_y1;
                        s2_in <= sat_state(acc1);
                        wcnt  <= '0;
                        state <= S_SEC2;
                    end else begin
                        wcnt <= wcnt + 1'b1;
                    end
                end

                S_SEC2: begin
                    if (wcnt == LAT) begin
                        s2_x1 <= s2_in;
                        s2_x2 <= s2_x1;
                        s2_y1 <= sat_state(acc2);
                        s2_y2 <= s2_y1;
                        y_sec <= sat_state(acc2);
                        state <= S_ROUND;
                    end else begin
                        wcnt <= wcnt + 1'b1;
                    end
                end

                // Load address and data one cycle BEFORE start_write rises
                S_ROUND: begin
                    val_out <= y_final;
                    address <= frame_addr_base + sample_off;
                    state   <= S_WRITE_REQ;
                end

                S_WRITE_REQ: begin
                    start_write <= 1'b1;
                    state       <= S_WRITE_WAIT;
                end

                S_WRITE_WAIT: begin
                    if (res_posedge) begin
                        start_write <= 1'b0;
                        if (sample_num == FRAME_LEN - 1) sample_num <= '0;
                        else                             sample_num <= sample_num + 1'b1;
                        state <= S_IDLE;
                    end
                end

                default: state <= S_IDLE;
            endcase
        end
    end

    // val_in is unused; keep lint quiet
    logic unused_ok;
    assign unused_ok = &{1'b0, val_in};

endmodule

`default_nettype wire
